mapper.select:
SELECT  FROM transactions t

ORDER BY t.authorized_at DESC, t.payment_id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO transactions (
    payment_id, payment_intent_id, public_payment_intent_id, merchant_account, buyer_id, order_id,
    psp_reference, processing_model, total_amount, currency, authorized_at, captured_at, settled_at,
    card_brand, card_last4
) VALUES (
    #{paymentId}, #{paymentIntentId}, #{publicPaymentIntentId}, #{merchantAccount}, #{buyerId}, #{orderId},
    #{pspReference}, #{processingModel}, #{totalAmount}, #{currency}, #{authorizedAt}, #{capturedAt}, #{settledAt},
    #{cardBrand}, #{cardLast4}
)
ON CONFLICT (payment_id) DO NOTHING
